CREATE TEMP TABLE stage_events (
  qid text PRIMARY KEY, title text, summary text,
  start_year int, start_month smallint, start_day smallint,
  end_year int, end_month smallint, end_day smallint,
  precision date_precision, display_date text, importance smallint, url text,
  event_id bigint
) ON COMMIT DROP;
CREATE TEMP TABLE stage_links (qid text, term_slug text, relevance real, is_primary boolean) ON COMMIT DROP;
CREATE TEMP TABLE stage_tags (qid text, tag_slug text) ON COMMIT DROP;

INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q4571240', '1963 Togolese coup d''état', 'The 1963 Togolese coup d''état was a military coup that occurred in the West African country of Togo on 13 January 1963. The coup leaders — notably Emmanuel Bodjollé, Étienne Eyadéma (later Gnassingbé Eyadéma) and Kléber Dadjo — took over government buildings, arrested most of the cabinet, and French Commander PAUC assassinated Togo''s first president, Sylvanus Olympio, outside the American embassy in Lomé.', 1963, 1, 13, NULL, NULL, NULL, 'day', '13 January 1963', 39, 'https://en.wikipedia.org/wiki/1963_Togolese_coup_d''%C3%A9tat'),
  ('Q16639048', '1967 Togolese coup d''état', 'The 1967 Togolese coup d''état was a bloodless military coup that occurred in the West African country of Togo on 13 January 1967. The leader of the coup, Lieutenant Colonel Étienne Eyadéma (later General Gnassingbé Eyadéma) ousted Togo''s second President, Nicolas Grunitzky, whom he essentially brought to power following the 1963 coup d''état.', 1967, 1, 13, NULL, NULL, NULL, 'day', '13 January 1967', 41, 'https://en.wikipedia.org/wiki/1967_Togolese_coup_d''%C3%A9tat'),
  ('Q728770', 'Lomé Peace Accord', 'The Lomé Peace Agreement was a peace agreement signed on 7 July 1999 between the warring parties in the civil war that gripped Sierra Leone for almost a decade. President Ahmad Tejan Kabbah signed with the Revolutionary United Front (RUF) leader, Foday Sankoh and granted Sankoh a position in the transitional government as well as amnesty for him and all combatants.', 1999, 7, 7, NULL, NULL, NULL, 'day', '7 July 1999', 39, 'https://en.wikipedia.org/wiki/Lom%C3%A9_Peace_Agreement'),
